export const defaultPalette=['#55c8ff','#ff8a65','#56dca1','#b5a0ff','#ffd166','#ff8fbb','#82b8ff','#9bdd7e'];
export const validColor=c=>typeof c==='string'&&/^#[a-f\d]{6}$/i.test(c);
const key=name=>name.trim().toLocaleLowerCase();
export function colorFromId(id,palette=defaultPalette){let n=2166136261;for(const c of String(id))n=Math.imul(n^c.charCodeAt(0),16777619);return palette[(n>>>0)%palette.length];}
export function pickColor(palette=defaultPalette,used=[]){const counts=palette.map(c=>used.filter(v=>v.toLowerCase()===c.toLowerCase()).length),least=Math.min(...counts),choices=palette.filter((_,i)=>counts[i]===least);const n=globalThis.crypto.getRandomValues(new Uint32Array(1))[0];return choices[n%choices.length];}
export function tagPath(tags,t){const p=tags.find(p=>p.id===t.parentId);return p?`${p.name} / ${t.name}`:t.name;}
export const systemTags=[{id:'daemon:main',name:'Main Mission',color:'#55c8ff',parentId:''},{id:'daemon:side',name:'Side Quest',color:'#ffd166',parentId:''}];
export const isSystemTag=id=>systemTags.some(t=>t.id===id);
export const tagOwners=(s,id)=>s.skills.filter(e=>e.boundTagId===id);
export const manualTags=s=>s.tags.filter(t=>!isSystemTag(t.id)&&!tagOwners(s,t.id).length);
export const lockedTag=(s,id)=>isSystemTag(id)||tagOwners(s,id).length>0;
export function linkedEntities(s,item){const selected=s.skills.filter(e=>(item.skills||[]).includes(e.id)),ids=new Set(selected.flatMap(e=>e.parentId?[e.id,e.parentId]:[e.id]));return s.skills.filter(e=>ids.has(e.id));}
export function itemTags(s,item){const entity=s.skills.find(e=>e.id===item.id),ids=[...(item.tagIds||[]),...(entity?[entity.boundTagId]:[]),...linkedEntities(s,item).map(e=>e.boundTagId),...(item.kind?[item.kind==='side'?'daemon:side':'daemon:main']:[])];return [...new Set(ids)].map(id=>s.tags.find(t=>t.id===id)).filter(Boolean);}
export function pairEntityTag(s,entity,tagId=''){
 if(tagId){if(isSystemTag(tagId)||!s.tags.some(t=>t.id===tagId))throw Error('Choose an Attribute or Skill tag.');entity.boundTagId=tagId;}
 else {const name=entity.title.trim().slice(0,60)||'Untitled',existing=s.tags.find(t=>!t.parentId&&!isSystemTag(t.id)&&key(t.name)===key(name));let tag=existing;
 if(!tag){let id='entity-'+String(entity.id).replace(/[^a-zA-Z0-9._:-]/g,'-').slice(0,170);while(s.tags.some(t=>t.id===id))id+='-';tag={id,name,color:colorFromId(entity.id,s.settings.calendar.palette),parentId:'',generatedFor:entity.id};s.tags.push(tag);}entity.boundTagId=tag.id;}
 s.tags.find(t=>t.id===entity.boundTagId).everBound=true;
 // A bound tag can only be applied through an entity selection.
 for(const item of [...s.missions,...s.skills,...s.rewards]){item.tagIds=(item.tagIds||[]).filter(id=>id!==entity.boundTagId);if(item.primaryTagId===entity.boundTagId&&!itemTags(s,item).some(t=>t.id===item.primaryTagId))item.primaryTagId='';}
 return entity.boundTagId;
}
export function syncEntityName(s,entity){const t=s.tags.find(t=>t.id===entity.boundTagId);if(t?.generatedFor===entity.id&&tagOwners(s,t.id).length===1){const name=entity.title.trim().slice(0,60);if(s.tags.some(other=>other.id!==t.id&&!isSystemTag(other.id)&&other.parentId===t.parentId&&key(other.name)===key(name)))throw Error('A tag with this name already exists. Pair that tag in the editor.');t.name=name;}}
export function matchesOrganization(s,item,filters={}){const entities=linkedEntities(s,item);return (!filters.attributes?.length||filters.attributes.some(id=>entities.some(e=>!e.parentId&&e.id===id)))&&(!filters.skills?.length||filters.skills.some(id=>entities.some(e=>e.parentId&&e.id===id)))&&(!filters.tags?.length||(filters.match==='all'?filters.tags.every(id=>hasTag(s,item,id)):filters.tags.some(id=>hasTag(s,item,id))));}

export function hasTag(s,item,id){if(isSystemTag(id))return !!item.kind&&id===(item.kind==='side'?'daemon:side':'daemon:main');return itemTags(s,item).some(t=>t.id===id||t.parentId===id);}
export function eventColor(s,m){const tags=itemTags(s,m),primary=tags.find(t=>t.id===m.primaryTagId)||tags.find(t=>!isSystemTag(t.id));return primary?.color||m.calendar.color;}
export function readableColor(hex,light=false){let rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));const lum=c=>{const n=c/255;return n<=.04045?n/12.92:((n+.055)/1.055)**2.4;},contrast=()=>{const l=rgb.reduce((sum,n,i)=>sum+lum(n)*[.2126,.7152,.0722][i],0);return light?1.05/(l+.05):(l+.05)/.07;};for(let i=0;i<20&&contrast()<4.5;i++)rgb=rgb.map(v=>Math.round(v*.9+(light?0:255)*.1));return '#'+rgb.map(v=>v.toString(16).padStart(2,'0')).join('');}
export function upgradeTags(s){if(!s||!s.settings||!Array.isArray(s.missions)||!Array.isArray(s.skills)||!Array.isArray(s.rewards))return s;s.settings.calendar??={palette:[...defaultPalette]};s.tags??=[];if(!Array.isArray(s.tags))return s;s.settings.calendar.palette??=[...defaultPalette];s.settings.calendar.autoDelete??=false;s.settings.calendar.retentionYears??=4;const ensure=name=>{let t=s.tags.find(t=>t&&typeof t.name==='string'&&!t.parentId&&key(t.name)===key(name));if(!t){let hash=2166136261;for(const c of key(name))hash=Math.imul(hash^c.charCodeAt(0),16777619);let id='legacy-'+(hash>>>0).toString(36);while(s.tags.some(t=>t?.id===id))id+='-';t={id,name:name.trim(),color:colorFromId(name),parentId:''};s.tags.push(t);}return t.id;};for(const item of [...s.missions,...s.skills,...s.rewards]){if(!item||typeof item!=='object')continue;if(item.tagIds===undefined){const names=[item.category,...(item.calendar?.tags||[])].filter(n=>typeof n==='string'&&n.trim());item.tagIds=[...new Set(names.map(ensure))];}item.primaryTagId??=item.tagIds?.[0]||'';if(item.calendar&&!item.calendar.colorAssigned){if(item.calendar.color==='#50f4d4')item.calendar.color=colorFromId(item.id,s.settings.calendar.palette);item.calendar.colorAssigned=true;}}for(const t of systemTags)if(!s.tags.some(x=>x.id===t.id)){for(const legacy of s.tags.filter(x=>x&&typeof x.name==='string'&&!x.parentId&&key(x.name)===key(t.name)&&!tagOwners(s,x.id).length)){let name=legacy.name+' (legacy)';while(s.tags.some(x=>x!==legacy&&x.parentId===''&&key(x.name)===key(name)))name+='-';legacy.name=name;}s.tags.push({...t});}for(const e of s.skills)if(e&&e.boundTagId===undefined)pairEntityTag(s,e);for(const e of s.skills){const tag=s.tags.find(t=>t.id===e.boundTagId);if(tag)tag.everBound=true;}for(const t of s.tags)if(t.everBound&&!t.parentId&&!tagOwners(s,t.id).length&&systemTags.some(f=>key(f.name)===key(t.name))){let name=t.name+' (unpaired)';while(s.tags.some(other=>other!==t&&other.parentId===''&&key(other.name)===key(name)))name+='-';t.name=name;}const locked=new Set(s.tags.filter(t=>lockedTag(s,t.id)).map(t=>t.id));for(const item of [...s.missions,...s.skills,...s.rewards]){if(Array.isArray(item.tagIds))item.tagIds=item.tagIds.filter(id=>!locked.has(id));if(item.primaryTagId&&!itemTags(s,item).some(t=>t.id===item.primaryTagId))item.primaryTagId='';}return s;}
export function validateTags(s){if(!Array.isArray(s.tags)||s.tags.length>5000||new Set(s.tags.map(t=>t?.id)).size!==s.tags.length)throw Error('Invalid tag catalog.');const names=new Set();for(const t of s.tags){if(!t||typeof t.id!=='string'||! /^[a-zA-Z0-9._:-]{1,200}$/.test(t.id)||typeof t.name!=='string'||!t.name.trim()||t.name.length>60||typeof t.parentId!=='string'||!validColor(t.color))throw Error('Invalid tag.');if(t.parentId&&!s.tags.some(p=>p.id===t.parentId&&!p.parentId&&p.id!==t.id))throw Error('Subtags must belong to a top-level tag.');if(!isSystemTag(t.id)&&!tagOwners(s,t.id).length&&systemTags.some(f=>!t.parentId&&key(f.name)===key(t.name)))throw Error('Main Mission and Side Quest tags are automatic and cannot be added manually.');const name=(isSystemTag(t.id)?'system:':'')+t.parentId+'\0'+key(t.name);if(names.has(name))throw Error('A tag with this name already exists in that group.');names.add(name);}const p=s.settings.calendar?.palette;if(!Array.isArray(p)||p.length<2||p.length>32||!p.every(validColor)||new Set(p.map(c=>c.toLowerCase())).size!==p.length)throw Error('Use 2–32 distinct calendar palette colors.');for(const item of [...s.missions,...s.skills,...s.rewards])if(!Array.isArray(item.tagIds)||item.tagIds.length>30||new Set(item.tagIds).size!==item.tagIds.length||!item.tagIds.every(id=>s.tags.some(t=>t.id===id))||typeof item.primaryTagId!=='string'||(item.primaryTagId&&!itemTags(s,item).some(t=>t.id===item.primaryTagId)))throw Error('Invalid item tag selection.');for(const e of s.skills)if(typeof e.boundTagId!=='string'||isSystemTag(e.boundTagId)||!s.tags.some(t=>t.id===e.boundTagId))throw Error('Every Attribute and Skill must have a paired tag.');for(const fixed of systemTags){const tag=s.tags.find(t=>t.id===fixed.id);if(!tag||Object.keys(fixed).some(k=>tag[k]!==fixed[k]))throw Error('Main Mission and Side Quest tags cannot be altered.');}if(typeof s.settings.calendar.autoDelete!=='boolean'||!Number.isInteger(s.settings.calendar.retentionYears)||s.settings.calendar.retentionYears<1||s.settings.calendar.retentionYears>8)throw Error('Calendar retention must be 1–8 years.');}
export function deleteTag(s,id){const ids=new Set([id,...s.tags.filter(t=>t.parentId===id).map(t=>t.id)]);if([...ids].some(tid=>lockedTag(s,tid)))throw Error('This tag is protected. Move every paired Attribute or Skill to another tag before deleting it.');s.tags=s.tags.filter(t=>!ids.has(t.id));for(const item of [...s.missions,...s.skills,...s.rewards]){item.tagIds=item.tagIds.filter(id=>!ids.has(id));if(ids.has(item.primaryTagId))item.primaryTagId=item.tagIds[0]||'';}}
export function calendarExportQuests(s){return s.missions.filter(m=>m.calendar.enabled&&!m.repeatable).map(m=>({...structuredClone(m),dateOverrides:s.calendarOverrides?.[m.seriesId]||{},calendar:{...m.calendar,color:eventColor(s,m),tags:(m.tagIds||[]).map(id=>s.tags.find(t=>t.id===id)).filter(Boolean).map(t=>t.name)},tagDefinitions:s.tags.filter(t=>m.tagIds.includes(t.id)||m.tagIds.some(id=>s.tags.find(c=>c.id===id)?.parentId===t.id))}));}
export function prepareCalendarTags(s,incoming,definitions=[]){const tags=structuredClone(s.tags),ensure=(name,parentId='',color)=>{let t=tags.find(t=>t.parentId===parentId&&key(t.name)===key(name));if(!t){t={id:globalThis.crypto.randomUUID(),name:name.trim(),parentId,color:validColor(color)?color:colorFromId(name)};tags.push(t);}return t;};const quests=incoming.map(m=>{const source=m.tagDefinitions||definitions,mapping=new Map();for(const t of source.filter(t=>!t.parentId))mapping.set(t.id,ensure(t.name,'',t.color).id);for(const t of source.filter(t=>t.parentId)){const parent=mapping.get(t.parentId);if(!parent)throw Error('Imported subtag has no parent definition.');mapping.set(t.id,ensure(t.name,parent,t.color).id);}const ids=(m.tagIds||[]).map(id=>mapping.get(id)||tags.find(t=>t.id===id)?.id);if(ids.some(id=>!id))throw Error('Imported quest is missing tag definitions.');if(!ids.length)for(const name of m.calendar?.tags||[])if(name.trim())ids.push(ensure(name).id);const tagIds=[...new Set(ids)];return {...m,tagIds,primaryTagId:mapping.get(m.primaryTagId)|| (tagIds.includes(m.primaryTagId)?m.primaryTagId:tagIds[0]||'')};});return {tags,quests};}
